Bad-controlled: corners are not turned

    
        Icosmominx
        Grigr\Icosmominx
        Michael Sun
        Evgeniy Grigoriev
        2017-01-23
        http://twistypuzzles.com/forum/viewtopic.php?f=15&t=359830
    

    
        R := 0.7;
        mAngle := ArcTan(0.5);
        Rsin := R * sin(mAngle);
        Rcos := R * cos(mAngle);
        As := sin(mAngle);
        Ac := cos(mAngle);
        sAngle := PI * 2 / 5;
        for i := 1 to 5 do begin
            x[i] := sin(sAngle * (i - 1)) * Ac;
            y[i] := cos(sAngle * (i - 1)) * Ac;
        end;

        D1 := (Rsin + 2 * R) / 3;
        D2 := (2 * Rsin + R) / 3;
        D3 := Rsin / 3;
